<?php
/** Plugin Name: Ferreta Core; Version: 1.0 */
declare(strict_types=1); namespace Ferreta; if(!defined('ABSPATH'))exit;
final class Core{static function boot(){add_action('init',[self::class,'init']);add_action('rest_api_init',[self::class,'rest']);add_action('woocommerce_product_options_inventory_product_data',[self::class,'fields']);add_action('woocommerce_admin_process_product_object',[self::class,'save']);add_action('woocommerce_order_status_changed',[self::class,'order'],10,4);add_action('woocommerce_checkout_create_order',[self::class,'utm'],10,2);}static function init(){register_post_type('ferreta_lead',['label'=>'Заявки Ferreta','public'=>false,'show_ui'=>true,'supports'=>['title','editor']]);register_post_type('ferreta_project',['label'=>'Проєкти','public'=>true,'show_ui'=>true,'supports'=>['title','editor','thumbnail']]);foreach(['height'=>'Висота','style'=>'Колекція','color'=>'Колір','space'=>'Простір']as$k=>$v)register_taxonomy('pa_'.$k,'product',['label'=>$v,'public'=>true,'show_ui'=>true]);if(!get_role('ferreta_sales')){add_role('ferreta_sales','Менеджер продажів',['read'=>true,'edit_ferreta_leads'=>true]);add_role('ferreta_content','Контент-менеджер',['read'=>true,'edit_posts'=>true,'upload_files'=>true,'edit_products'=>true]);add_role('ferreta_warehouse','Склад/виробництво',['read'=>true,'edit_products'=>true]);}}static function rest(){register_rest_route('ferreta/v1','/lead',['methods'=>'POST','callback'=>[self::class,'lead'],'permission_callback'=>'__return_true']);}static function lead($r){$d=$r->get_json_params();if(empty($d['name'])||empty($d['phone'])||empty($d['consent']))return new \WP_Error('required','Заповніть обов’язкові поля',['status'=>422]);$id=wp_insert_post(['post_type'=>'ferreta_lead','post_status'=>'publish','post_title'=>sanitize_text_field($d['name'])]);foreach(['type','name','phone','email','comment','utm_source']as$k)update_post_meta($id,'_ferreta_'.$k,sanitize_textarea_field($d[$k]??''));update_post_meta($id,'_ferreta_status','new');self::tg("🔔 Нова заявка #$id\n".sanitize_text_field($d['name']).' · '.sanitize_text_field($d['phone']));return new \WP_REST_Response(['id'=>$id],201);}static function fields(){woocommerce_wp_text_input(['id'=>'_ferreta_barcode','label'=>'Штрихкод']);woocommerce_wp_text_input(['id'=>'_ferreta_cost','label'=>'Собівартість','type'=>'number']);woocommerce_wp_text_input(['id'=>'_ferreta_min_stock','label'=>'Мінімальний залишок','type'=>'number']);}static function save($p){foreach(['_ferreta_barcode','_ferreta_cost','_ferreta_min_stock']as$k)$p->update_meta_data($k,wc_clean($_POST[$k]??''));}static function utm($order,$data){foreach(['utm_source','utm_medium','utm_campaign']as$k)if(isset($_COOKIE[$k]))$order->update_meta_data('_ferreta_'.$k,sanitize_text_field($_COOKIE[$k]));}static function order($id,$f,$t,$o){if(in_array($t,['processing','completed']))self::tg("💳 Оплачено #$id");}static function tg($text){$token=defined('FERRETA_TELEGRAM_BOT_TOKEN')?FERRETA_TELEGRAM_BOT_TOKEN:'';$chats=defined('FERRETA_TELEGRAM_CHAT_IDS')?array_filter(array_map('trim',explode(',',FERRETA_TELEGRAM_CHAT_IDS))):[];if(!$token||!$chats){error_log('[Ferreta] Telegram test mode: '.$text);return;}foreach($chats as$chat){$r=wp_remote_post("https://api.telegram.org/bot{$token}/sendMessage",['timeout'=>15,'body'=>['chat_id'=>$chat,'text'=>$text]]);if(is_wp_error($r)||wp_remote_retrieve_response_code($r)>=300)error_log('[Ferreta] Telegram error: '.(is_wp_error($r)?$r->get_error_message():wp_remote_retrieve_response_code($r)));}}}
Core::boot();
